            aWandererA = aWandererA ^ (((RotL64(aScatter, 43U) + RotL64(aOrbiterE, 11U)) + aOrbiterA) + aWUSaltA[(((511U - aIndex) + 199U)) & S_SALT1]);
            aWandererK = aWandererK + (((RotL64(aPrevious, 57U) + aOrbiterI) + RotL64(aOrbiterG, 5U)) + aNonceWordE);
            aWandererH = aWandererH ^ ((RotL64(aCross, 53U) + RotL64(aOrbiterC, 60U)) + aOrbiterE);
            aWandererG = aWandererG + (((RotL64(aIngress, 46U) + RotL64(aOrbiterA, 41U)) + aOrbiterF) + aNonceWordJ);
            //
            aCarry = aCarry + (aWandererG ^ RotL64(aWandererF, 60U));
