            aScatter = TwistMix64::DiffuseC(((aScatter ^ aSeedDomainWordScatter) ^ aNonceWordI));
            //
            aOrbiterB = (((aWandererC + RotL64(aCross, 13U)) + 0x69EBF0A31A3E7E9CULL) + aOASaltC[((aIndex + 187U)) & S_SALT1]) + aNonceWordO;
            aOrbiterI = ((aWandererG + RotL64(aIngress, 27U)) + 0xE733296EAEAAC26DULL) + aNonceWordH;
