            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0xFC39AB3377DC9F91ULL) ^ aOUSaltG[((aIndex + 105U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9EB55899D8316B7DULL), 43U);
