            aCross = (RotL64(aWindLaneC[((S_BLOCK1 - aIndex + 6833U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneA[((S_BLOCK1 - aIndex + 7214U)) & S_BLOCK1], 39U));
