            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 37U) ^ RotL64(aIngress, 10U)) ^ (RotL64(aPrevious, 51U) + RotL64(aCarry, 23U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = (aWandererF + RotL64(aIngress, 19U)) + 0xFD854DF30A908EFCULL;
            aOrbiterA = ((aWandererH + RotL64(aScatter, 40U)) + 0x887A9CCA631CE921ULL) + aOASaltB[(((511U - aIndex) + 59U)) & S_SALT1];
            aOrbiterG = (((aWandererC + RotL64(aPrevious, 53U)) + RotL64(aCarry, 23U)) + 0x0C2A73E7CA87DD5DULL) + aOASaltD[(((511U - aIndex) + 49U)) & S_SALT1];
            aOrbiterH = ((aWandererK + RotL64(aCross, 27U)) + 0xA8207A8AB66FD9FBULL) + aOASaltH[((aIndex + 127U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aIngress, 21U)) + 0xA78B3B05C2B6C431ULL;
            aOrbiterI = (((aWandererD + RotL64(aScatter, 6U)) + RotL64(aCarry, 29U)) + 0x346B4C14C11C97A9ULL) + aOASaltG[(((511U - aIndex) + 149U)) & S_SALT1];
