            //
            aOrbiterB = (aOrbiterB + aOrbiterA) + 0x73969F904D9FCC78ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterB) ^ 0x06C34B27E5B50A27ULL) ^ aOUSaltC[((aIndex + 190U)) & S_SALT1];
