            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateBDomainWordScatter));
            //
            aOrbiterG = (aWandererC + RotL64(aScatter, 4U)) + 0x9454C3929EAF292FULL;
            aOrbiterA = ((aWandererD + RotL64(aPrevious, 11U)) + RotL64(aCarry, 21U)) + 0x7289847A50BD636CULL;
